    bPump2 : BOOL;     // Estado de la bomba 2
    bPump1Stopped : BOOL; // Indicador de que la bomba 1 está detenida
END_VAR

// Lógica de control
IF bPump1 = FALSE THEN
    bPump1Stopped := TRUE;
ELSE
    bPump1Stopped := FALSE;
END_IF;

// La bomba 2 solo se activa cuando la bomba 1 está detenida
IF bPump1Stopped = TRUE THEN
    bPump2 := TRUE;
ELSE
    bPump2 := FALSE;
END_IF;

// La bomba 1 puede activarse independientemente, pero no se activará si la bomba 2 está activa
// (esto se puede implementar con una lógica de exclusión, aunque no se especifica en el enunciado
// si se debe evitar que la bomba 1 se active si la bomba 2 está activa, se asume que no es requerido
// por el enunciado, por lo que se omite esta restricción adicional).

// Si se requiere que la bomba 1 no se active si la bomba 2 está activa, se añadiría:
// IF bPump2 = TRUE THEN
