```iecst
PROGRAM MAIN
VAR
    bSensor : BOOL;
    fbTimer : TON;
    bAlarm : BOOL;
END_VAR

fbTimer(IN := bSensor, PT := T#3S);
bAlarm := fbTimer.Q;
```

